+        font-size: 1.05rem;
+        line-height: 1.7;
+      }
+
+      .faq {
+        display: grid;
+        gap: 16px;
+      }
+
+      .example {
+        border: 1px solid var(--panel-border);
+        border-radius: 20px;
+        background: linear-gradient(180deg, rgba(15, 23, 42, 0.92), rgba(15, 23, 42, 0.72));
+        box-shadow: var(--shadow);
+        overflow: hidden;
+        backdrop-filter: blur(12px);
+      }
+
+      .question {
+        width: 100%;
+        border: 0;
+        padding: 22px 24px;
+        display: flex;
+        align-items: center;
+        justify-content: space-between;
+        gap: 16px;
+        background: transparent;
+        color: var(--text);
+        cursor: pointer;
+        text-align: left;
+        font: inherit;
+      }
+
+      .question:hover {
+        background: rgba(124, 219, 255, 0.05);
+      }
+
+      .question h2 {
+        margin: 0;
+        font-size: 1.08rem;
+        line-height: 1.4;
+      }
+
+      .chevron {
+        flex: 0 0 auto;
+        width: 38px;
+        height: 38px;
+        display: grid;
+        place-items: center;
+        border-radius: 999px;
+        background: rgba(148, 163, 184, 0.12);
+        color: var(--accent);
+        transition: transform 180ms ease, background 180ms ease;
+      }
+
+      .example.is-open .chevron {
+        transform: rotate(180deg);
+        background: rgba(56, 189, 248, 0.16);
+      }
+
+      .details {
+        padding: 0 24px 22px;
+        color: var(--muted);
+        line-height: 1.75;
+      }
+
+      .details[hidden] {
+        display: none;
+      }
+
+      .details p {
+        margin: 0;
+      }
+
+      @media (max-width: 640px) {
+        .app {
+          width: min(100% - 20px, 920px);
+          padding-top: 32px;
+        }
+
+        .question,
+        .details {
+          padding-left: 18px;
+          padding-right: 18px;
+        }
+      }
+    </style>
+  </head>
+  <body>
+    <main id="root"></main>
+
+    <script>
+      const faqData = [
+        {
+          question: "Why do cats purr?",
+          answer:
+            "Cats purr for many reasons: contentment, relaxation, and sometimes self-soothing when they feel stressed or unwell. It's one of their most iconic forms of communication."
+        },
+        {
+          question: "How much sleep do cats need?",
+          answer:
+            "Most cats sleep between 12 and 16 hours a day, and some can rest even longer. Their bursts of energy are usually short, which is why they seem sleepy for much of the day."
+        },
+        {
+          question: "Why do cats knead with their paws?",
+          answer:
+            "Kneading is a comforting behavior that often starts in kittenhood. Adult cats may knead when they feel safe, affectionate, or relaxed."
+        },
+        {
+          question: "Do cats recognize their names?",
+          answer:
+            "Yes, many cats learn to recognize their names, even if they don't always respond. They usually associate the sound with attention, food, or routine."
+        },
+        {
+          question: "Why do cats bring gifts?",
+          answer:
+            "Cats may bring toys, prey, or random objects as part of their hunting instincts or social behavior. It's not always a gift in the human sense, but it often signals engagement."
+        }
+      ];
+
+      function FAQItem({ question, answer, index }) {
+        const item = document.createElement("section");
+        item.className = "example";
+
+        const button = document.createElement("button");
+        button.className = "question";
+        button.type = "button";
+        button.setAttribute("aria-expanded", "false");
+        button.setAttribute("aria-controls", `faq-answer-${index}`);
+
+        const title = document.createElement("h2");
+        title.textContent = question;
+
+        const chevron = document.createElement("span");
+        chevron.className = "chevron";
+        chevron.setAttribute("aria-hidden", "true");
+        chevron.textContent = "⌄";
+
+        button.append(title, chevron);
+
+        const details = document.createElement("div");
+        details.className = "details";
+        details.id = `faq-answer-${index}`;
+        details.hidden = true;
+
+        const paragraph = document.createElement("p");
+        paragraph.textContent = answer;
+        details.appendChild(paragraph);
+
+        button.addEventListener("click", () => {
+          const open = item.classList.toggle("is-open");
+          button.setAttribute("aria-expanded", String(open));
+          details.hidden = !open;
+        });
+
+        item.append(button, details);
+        return item;
+      }
+
+      function FAQPage() {
+        const app = document.createElement("div");
+        app.className = "app";
+
+        const hero = document.createElement("header");
+        hero.className = "hero";
+
+        const eyebrow = document.createElement("div");
+        eyebrow.className = "eyebrow";
+        eyebrow.textContent = "Cat FAQ";
+
+        const heading = document.createElement("h1");
+        heading.textContent = "Everything you want to know about cats";
+
+        const lead = document.createElement("p");
+        lead.className = "lead";
+        lead.textContent =
+          "A polished, expandable FAQ with answers hidden by default. Tap a question to reveal the details.";
+
+        hero.append(eyebrow, heading, lead);
+
+        const list = document.createElement("div");
+        list.className = "faq";
+        faqData.forEach((item, index) => {
+          list.appendChild(FAQItem({ ...item, index }));
+        });
+
+        app.append(hero, list);
+        return app;
+      }
+
+      document.getElementById("root").appendChild(FAQPage());
+    </script>
+  </body>
+</html>
*** End Patch
