         const chevron = document.createElement("span");
         chevron.className = "chevron";
         chevron.setAttribute("aria-hidden", "true");
         chevron.textContent = "⌄";

         button.append(title, chevron);

         const details = document.createElement("div");
         details.className = "details";
         details.id = `faq-answer-${index}`;
         details.hidden = true;

         const paragraph = document.createElement("p");
         paragraph.textContent = answer;
         details.appendChild(paragraph);

         button.addEventListener("click", () => {
           const open = item.classList.toggle("is-open");
           button.setAttribute("aria-expanded", String(open));
           details.hidden = !open;
         });

         item.append(button, details);
         return item;
       }

       function FAQPage() {
         const app = document.createElement("div");
         app.className = "app";

         const hero = document.createElement("header");
         hero.className = "hero";

         const eyebrow = document.createElement("div");
         eyebrow.className = "eyebrow";
         eyebrow.textContent = "Cat FAQ";

         const heading = document.createElement("h1");
         heading.textContent = "Everything you want to know about cats";

         const lead = document.createElement("p");
         lead.className = "lead";
         lead.textContent =
           "A polished, expandable FAQ with answers hidden by default. Tap a question to reveal the details.";

         hero.append(eyebrow, heading, lead);

         const list = document.createElement("div");
         list.className = "faq";
         faqData.forEach((item, index) => {
           list.appendChild(FAQItem({ ...item, index }));
         });

         app.append(hero, list);
         return app;
       }

       document.getElementById("root").appendChild(FAQPage());
     </script>
   </body>
